'use strict';

// Compiles schema/drumdrom.schema.json with ajv at build time and writes the
// validator as plain JavaScript to lib/generated/validate-schema.js (git-ignored).
// The generated file has no ajv import and no runtime code generation, so the
// browser bundle stays small and works under a strict Content-Security-Policy.
// Run by `npm run build-validator`, and by the prepare, pretest, prelint and
// prebuild scripts.
const fs = require('fs');
const path = require('path');
const Ajv2020 = require('ajv/dist/2020');
const standaloneCode = require('ajv/dist/standalone').default;
const esbuild = require('esbuild');

const root = path.join(__dirname, '..');
const schemaFile = path.join(root, 'schema', 'drumdrom.schema.json');
const outFile = path.join(root, 'lib', 'generated', 'validate-schema.js');

const header = '// Generated by scripts/build-validator.js from schema/drumdrom.schema.json. Do not edit.\n';

// The options must match what the tests compile at runtime for comparison
const ajvOptions = { allErrors: true, strict: true, allowUnionTypes: true };

function generate() {
  const schema = JSON.parse(fs.readFileSync(schemaFile, 'utf8'));
  const ajv = new Ajv2020({ ...ajvOptions, code: { source: true } });
  const code = standaloneCode(ajv, ajv.compile(schema));
  // The standalone code requires a few small ajv runtime helpers: inline them
  const result = esbuild.buildSync({
    stdin: { contents: code, resolveDir: root, loader: 'js' },
    bundle: true,
    platform: 'neutral',
    mainFields: ['main'],
    format: 'cjs',
    write: false,
    legalComments: 'none'
  });
  return header + "'use strict';\n" + result.outputFiles[0].text;
}

if (require.main === module) {
  fs.mkdirSync(path.dirname(outFile), { recursive: true });
  const code = generate();
  // Leave the file alone when unchanged so file watchers stay quiet
  if (!fs.existsSync(outFile) || fs.readFileSync(outFile, 'utf8') !== code) {
    fs.writeFileSync(outFile, code, 'utf8');
    process.stdout.write('wrote ' + path.relative(root, outFile) + '\n');
  }
}

module.exports = { generate, ajvOptions, outFile };
